# List questions without a published explanation, for filing issues.
# Run from the repo root: python3 tools/explanations/missing.py > docs/dev_plans/missing-explanations.md
import json, os
pools = json.load(open('app/data/pools.json'))['pools']
L = 'ABCD'
out = ['# Questions without an explanation', '',
       'Generated by `tools/explanations/missing.py`. "Withheld" questions were looked at and need a source or a decision; '
       'the reason comes from `tools/explanations/<pool>/withheld.json`. "Not written yet" questions just haven\'t been done.', '']
later = []
for p in pools:
    f = f'app/data/explanations/{p["id"]}.json'
    if not os.path.exists(f):
        later.append(f'- {p["name"]} ({p["id"]}): all {len(p["q"])} questions')
        continue
    ex = json.load(open(f))['q']
    wf = f'tools/explanations/{p["id"]}/withheld.json'
    wh = json.load(open(wf)) if os.path.exists(wf) else {}
    sec_of = {i: (s, g) for s in p['sections'] for g in s['g'] for i in g['q']}
    miss = [(i, q) for i, q in enumerate(p['q']) if q[0] not in ex]
    held = [(i, q) for i, q in miss if q[0] in wh]
    todo = [(i, q) for i, q in miss if q[0] not in wh]
    out += [f'## {p["name"]} ({p["id"]})', '', f'{len(ex)} of {len(p["q"])} explained, {len(held)} withheld, {len(todo)} not written yet.', '']
    if held:
        out += ['### Withheld', '']
        for i, q in held:
            s, g = sec_of[i]
            out += [f'- **{q[0]}** (topic {g["id"]}, {g["t"]}): {q[1]}', f'  - Key: {L[q[3]]}. {q[2][q[3]]}', f'  - Why withheld: {wh[q[0]]}']
        out.append('')
    if todo:
        out += ['### Not written yet, by subelement', '']
        by = {}
        for i, q in todo:
            s, g = sec_of[i]
            by.setdefault(f'{s["id"]} {s["t"]}', []).append(q[0])
        out += [f'- {k}: {len(v)} questions ({v[0]} to {v[-1]})' for k, v in by.items()] + ['']
if later:
    out += ['## Exams with no explanations yet', ''] + later + ['']
print('\n'.join(out))
